  function generateUtility(s,tenantId,roomId){const r=requireRoom(s,tenantId,roomId);ensure(s);if(!['电表','水表'].every(t=>Core.bound(r,t)))throw Error('水电表未安装齐全，不能生成合并账单');const period=TODAY.slice(0,7);if(s.bills.some(b=>b.tenantId===tenantId&&b.roomId===roomId&&b.period===period&&b.kind==='水电费'&&b.status!=='void'))return 0;const items=[];for(const type of ['电表','水表']){const a=account(s,tenantId,roomId,type),value=r[type==='电表'?'electric':'water'];if(a.serviceFee)items.push({label:type+'服务费',amount:a.serviceFee});if(a.sharedFee)items.push({label:type+'公摊费',amount:a.sharedFee});if(a.mode!=='postpaid')continue;const usage=Math.max(0,Math.round((value-a.lastBilled)*100)/100);items.push({label:`${type} ${a.lastBilled} → ${value} · ${usage} × ${money(a.rate)} · 费率v${a.rateVersion}`,amount:usageCharge(a,a.lastBilled,value)});}if(!items.length)return 0;const b={id:id('utility'),tenantId,roomId,period,kind:'水电费',amount:items.reduce((a,i)=>a+i.amount,0),resident:r.resident,status:'unpaid',due:'2026-10-28',items};s.bills.unshift(b);for(const type of ['电表','水表']){const a=account(s,tenantId,roomId,type);if(a.mode==='postpaid')a.lastBilled=r[type==='电表'?'electric':'water']}note(s,tenantId,'缴费','水电账单已生成',r.number+' · '+money(b.amount),roomId);return 1}
  function recharge(s,tenantId,roomId,type,value){const r=requireRoom(s,tenantId,roomId),a=account(s,tenantId,roomId,type);if(!Core.bound(r,type)||a.mode!=='prepaid')throw Error('请先安装表计并设置预付费模式');const amount=cents(value,a.minimum);const bill={id:id('bill'),tenantId,roomId,period:TODAY.slice(0,7),kind:type+'预充值',amount,resident:r.resident||'演示住户',status:'unpaid',due:TODAY,items:[{label:type+'预充值（设备确认后到账）',amount}]};const rec={id:id('charge'),tenantId,roomId,accountId:a.id,billId:bill.id,type,amount,status:'待支付',credited:false,time:TODAY+' '+clock()};s.bills.unshift(bill);s.recharges.unshift(rec);return rec}
  function deliverRecharge(s,tenantId,rechargeId){const rec=get(s,'recharges',tenantId,rechargeId),r=requireRoom(s,tenantId,rec.roomId),a=get(s,'meterAccounts',tenantId,rec.accountId);const bill=s.bills.find(b=>b.id===rec.billId);if(bill?.status!=='paid')throw Error('请先完成模拟支付');if(rec.credited)return rec;if(!online(s,r,rec.type)){rec.status='待同步';return rec}a.deviceBalance+=rec.amount;rec.credited=true;rec.status='已到账（模拟）';log(s,tenantId,'表计充值确认（模拟）',rec.id,'财务');return rec}
  function pay(s,tenantId,billId,method){ensure(s);const b=s.bills.find(b=>b.id===billId&&b.tenantId===tenantId);const changed=Core.pay(s,tenantId,billId);if(!changed)return false;s.transactions[0].date=TODAY;if(method)s.transactions[0].method=method;const rec=s.recharges.find(c=>c.billId===billId);if(rec){const a=get(s,'meterAccounts',tenantId,rec.accountId);a.balance+=rec.amount;deliverRecharge(s,tenantId,rec.id)}if(b.contractId){const c=get(s,'contracts',tenantId,b.contractId);activate(s,tenantId,c)}note(s,tenantId,'缴费','模拟收款已确认',b.kind+' · '+money(b.amount),b.roomId);return true}
  function adjustBill(s,tenantId,billId,f){ensure(s);const b=s.bills.find(b=>b.id===billId&&b.tenantId===tenantId);if(!b||b.status!=='unpaid'||b.contractId||s.recharges.some(r=>r.billId===b.id))throw Error('仅普通待收账单可调整，首期及充值应撤回重建');if(!f.reason?.trim())throw Error('请填写调整原因');if(f.action==='void')b.status='void';else{const amount=cents(f.amount);b.originalAmount??=b.amount;b.amount=amount;b.items=[{label:'人工审批调整（演示）：'+f.reason,amount}]}log(s,tenantId,'审批调整账单（模拟）',b.id+' · '+f.reason,'财务')}
  function requestRefund(s,tenantId,billId,f){ensure(s);const b=s.bills.find(b=>b.id===billId&&b.tenantId===tenantId&&b.status==='paid');if(!b)throw Error('请选择已支付账单');const refundKind=f.refundKind||(b.kind.includes('预充值')?'水电退款':/房租|租金/.test(b.kind)?'租金退款':'其他退款');const amount=cents(f.amount,1),used=s.refunds.filter(x=>x.billId===b.id&&x.status!=='rejected').reduce((n,x)=>n+x.amount,0);if(used+amount>b.amount)throw Error('退款累计金额不能超过实收');if(!f.reason?.trim())throw Error('请填写退款原因');if(refundKind==='租金退款'){const rent=(b.items||[]).filter(i=>/租金|房租/.test(i.label)&&!i.label.includes('押金')).reduce((n,i)=>n+i.amount,0),already=s.refunds.filter(r=>r.billId===b.id&&r.refundKind==='租金退款'&&r.status!=='rejected').reduce((n,r)=>n+r.amount,0);if(!rent||already+amount>Math.min(rent,b.amount))throw Error('该账单可退租金不足，押金请单列申请')}if(refundKind==='押金退还'){const deposit=(b.items||[]).filter(i=>i.label.includes('押金')).reduce((n,i)=>n+i.amount,0),already=s.refunds.filter(r=>r.billId===b.id&&r.refundKind==='押金退还'&&r.status!=='rejected').reduce((n,r)=>n+r.amount,0);if(!deposit||already+amount>deposit)throw Error('该账单可退押金不足')}const rf={id:id('refund'),tenantId,billId,roomId:b.roomId,amount,refundKind,reason:f.reason.trim(),status:'pending',time:TODAY+' '+clock()};s.refunds.unshift(rf);log(s,tenantId,'申请退款（模拟）',rf.id,'财务');return rf}
  function refundAction(s,tenantId,refundId,action){const rf=get(s,'refunds',tenantId,refundId);if(rf.status!=='pending')throw Error('退款已处理');if(action==='approve'){const rec=s.recharges.find(r=>r.billId===rf.billId);if(rec){const a=get(s,'meterAccounts',tenantId,rec.accountId),r=requireRoom(s,tenantId,rec.roomId);if(!rec.credited||!online(s,r,rec.type)||rf.amount>a.deviceBalance||rf.amount>a.balance)throw Error('充值未到账、表计离线或可退余额不足，请先复核');a.balance-=rf.amount;a.deviceBalance-=rf.amount}rf.status='completed';rf.completedAt=clock();if(s.settlements.some(st=>st.tenantId===tenantId&&['approved','paid'].includes(st.status)&&st.lines.some(l=>l.billId===rf.billId)))note(s,tenantId,'财务','渠道佣金需核对冲销',rf.id+' · 请生成服务商结算/冲销单',rf.roomId)}else if(action==='reject')rf.status='rejected';else throw Error('请选择批准或驳回');note(s,tenantId,'财务','退款处理结果（模拟）',rf.id+' · '+rf.status,rf.roomId);log(s,tenantId,'退款复核 · '+action+'（模拟）',rf.id,'财务')}
