  function settlementAction(s,tenantId,settlementId,action){const st=get(s,'settlements',tenantId,settlementId);if(action==='approve'&&st.status==='draft'){if(st.lines.some(l=>!l.refundId&&rentBase(s,s.bills.find(b=>b.id===l.billId))!==l.base))throw Error('结算基数因退款变化，请作废草稿后重新生成');st.status='approved';}else if(action==='pay'&&st.status==='approved'){st.status='paid';st.paidAt=clock()}else if(action==='void'&&st.status==='draft')st.status='void';else throw Error('结算状态已变化，不能重复处理');log(s,tenantId,'服务商结算 · '+action+'（模拟）',st.id,'财务')}
  function service(s,tenantId,roomId,f){ensure(s);const t=Core.ticket(s,tenantId,roomId,f);Object.assign(t,{serviceKind:f.serviceKind||'报修',appointment:f.appointment||'',contact:f.contact||'',photos:f.photos||[],timeline:[{time:clock(),text:'提交'+(f.serviceKind||'报修')}],rating:0});note(s,tenantId,'工单','新的服务申请',t.title,roomId);return t}
  function serviceAction(s,tenantId,ticketId,action,f={}){ensure(s);const t=s.tickets.find(t=>t.id===ticketId&&t.tenantId===tenantId);if(!t)throw Error('工单不存在或无权访问');t.timeline ||= [];if(action==='assign'){if(!['pending','processing'].includes(t.status))throw Error('该工单当前不可派单');const tech=s.technicians.find(x=>x.tenantId===tenantId&&x.id===f.techId&&x.active);if(!tech)throw Error('请选择在岗维修人员');t.assignee=tech.name;t.techId=tech.id;t.appointment=f.appointment||t.appointment;t.status='processing'}else if(action==='start'){if(t.status!=='processing')throw Error('请先受理派单');t.startedAt=clock()}else if(action==='resolve'){if(t.status!=='processing'||!f.record?.trim())throw Error('请填写维修说明');t.record=f.record;t.cost=cents(f.cost||0);t.materials=f.materials||'';t.afterPhotos=f.photos||[];t.status='resolved';t.resolvedAt=clock()}else if(action==='confirm'){if(t.status!=='resolved')throw Error('请先完成服务');t.status='closed'}else if(action==='review'){if(t.status!=='closed'||t.rating)throw Error('完成的工单仅可评价一次');const rating=Number(f.rating);if(!Number.isInteger(rating)||rating<1||rating>5)throw Error('请选择1–5星评分');t.rating=rating;t.review=f.review||''}else if(action==='cancel'){if(!['pending','processing'].includes(t.status)||!f.reason?.trim())throw Error('请填写取消原因，已完成工单不可取消');t.status='cancelled';t.cancelReason=f.reason}else if(action==='urge'){if(!['pending','processing'].includes(t.status))throw Error('该工单无需催办')}else throw Error('不支持的服务操作');t.timeline.push({time:clock(),text:action+' · '+(f.record||f.reason||t.assignee||'')});note(s,tenantId,'工单','服务进度更新',t.title+' · '+t.status,t.roomId);log(s,tenantId,'服务处理 · '+action,t.id,'工单');return t}
  function suggestTech(s,tenantId,ticketId){ensure(s);const t=s.tickets.find(t=>t.id===ticketId&&t.tenantId===tenantId);if(!t)throw Error('工单不存在');const r=requireRoom(s,tenantId,t.roomId);return s.technicians.filter(x=>x.tenantId===tenantId&&x.active).map(x=>({...x,load:s.tickets.filter(t=>t.techId===x.id&&t.status==='processing').length,score:(x.propertyId===r.propertyId?2:0)+(x.skill===t.type?1:0)})).sort((a,b)=>b.score-a.score||a.load-b.load)[0]}
  function inspectCheckout(s,tenantId,roomId,f){ensure(s);const r=requireRoom(s,tenantId,roomId);if(r.status!=='occupied'||!f.inspected)throw Error('请确认已完成演示验房');const e=Number(f.electric),w=Number(f.water);if(!Number.isFinite(e)||!Number.isFinite(w)||e<r.electric||w<r.water)throw Error('末次读数不能小于已有读数');const repair=cents(f.repair||0),electricAccount=account(s,tenantId,roomId,'电表'),waterAccount=account(s,tenantId,roomId,'水表'),usageDue=(electricAccount.mode==='postpaid'?usageCharge(electricAccount,electricAccount.lastBilled,e):0)+(waterAccount.mode==='postpaid'?usageCharge(waterAccount,waterAccount.lastBilled,w):0);const due=usageDue+s.bills.filter(b=>b.tenantId===tenantId&&b.roomId===roomId&&b.status==='unpaid').reduce((n,b)=>n+b.amount,0);const settle={id:id('checkout'),tenantId,roomId,resident:r.resident,electric:e,water:w,repair,usageDue,due,deposit:r.deposit,refund:Math.max(0,r.deposit-due-repair),remaining:Math.max(0,due+repair-r.deposit),status:'待复核',date:TODAY};if(s.inspections.some(x=>x.roomId===roomId&&x.status!=='cancelled'))throw Error('该房间已有退租验房记录');s.inspections.unshift(settle);log(s,tenantId,'完成退租验房（模拟）',r.number);return settle}
