  function cleanRoom(s,tenantId,roomId){const r=requireRoom(s,tenantId,roomId);ensure(s);if(r.status==='turnover'){const pending=s.commands.filter(c=>c.roomId===r.id&&c.action.includes('撤')&&c.status!=='已确认');if(!online(s,r,'门锁')||pending.length)throw Error('撤权尚未确认，请先恢复设备并重试撤权任务')}else if(r.status!=='cleaning')throw Error('该房间无需清洁交付');r.status='vacant';r.grant='已撤销';(s.grants||[]).filter(g=>g.roomId===r.id).forEach(g=>g.status='已撤销');s.credentials.filter(g=>g.roomId===r.id&&g.requestedStatus==='已撤销').forEach(g=>g.status='已撤销');s.inspections.filter(i=>i.roomId===r.id&&i.status!=='cancelled').forEach(i=>i.status='已完成');log(s,tenantId,'确认清洁交付（模拟）',r.number)}
  function notifySettings(s,tenantId,f){ensure(s);const cfg=s.config[tenantId];if(!['仅提醒，人工复核','提醒＋人工审批水电操作'].includes(f.arrears))throw Error('不支持自动锁门策略');const apiBase=String(f.apiBase||'').trim();if(apiBase&&!/^https:\/\/[^\s@?#]+\/?[^\s?#]*$/.test(apiBase))throw Error('接口地址请使用不带凭据、查询参数的 HTTPS 地址');Object.assign(cfg,{arrears:f.arrears,graceDays:Math.max(0,Math.min(30,Number(f.graceDays)||0)),apiEnvironment:['未接入','测试环境待联调','生产环境待验收'].includes(f.apiEnvironment)?f.apiEnvironment:'未接入',apiBase,brand:f.brand||cfg.brand,reportSchedule:f.reportSchedule||cfg.reportSchedule,notifyChannels:['站内信']});log(s,tenantId,'更新演示配置','接口与策略仅记录配置，不实际连接')}
